function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 3500) return 'nums needs 1 to 3500 lists.';
  for (const list of nums) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 50) return 'Each list needs 1 to 50 numbers.';
    for (let j = 0; j < list.length; j++) {
      if (!Number.isInteger(list[j]) || list[j] < -100000 || list[j] > 100000) return 'Each number is an integer between -100000 and 100000.';
      if (j > 0 && list[j] < list[j - 1]) return 'Each list must be sorted in non-decreasing order.';
    }
  }
  return null;
}

