function smallestRange(nums) {
  const heap = [];
  const swap = (a, b) => {
    [heap[a], heap[b]] = [heap[b], heap[a]];
  };
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0 && heap[(child - 1) >> 1][0] > heap[child][0]) {
      swap(child, (child - 1) >> 1);
      child = (child - 1) >> 1;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      for (;;) {
        let smallest = parent;
        const left = 2 * parent + 1;
        const right = left + 1;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === parent) break;
        swap(parent, smallest);
        parent = smallest;
      }
    }
    return top;
  };

  let high = -Infinity;
  for (let list = 0; list < nums.length; list++) {
    push([nums[list][0], list, 0]);
    high = Math.max(high, nums[list][0]);
  }
  let best = [heap[0][0], high];
  for (;;) {
    const [low, list, index] = pop();
    if (high - low < best[1] - best[0]) {
      best = [low, high];
    }
    if (index + 1 === nums[list].length) {
      return best;
    }
    const next = nums[list][index + 1];
    push([next, list, index + 1]);
    high = Math.max(high, next);
  }
}

