function smallestRange(nums) {
  // Try every element as the left end; the right end is then forced:
  // the largest of each list's first element at or above it.
  const values = [...new Set(nums.flat())].sort((x, y) => x - y);
  let best = null;
  for (const a of values) {
    let b = a;
    let covered = true;
    for (const list of nums) {
      const hit = list.find(v => v >= a);
      if (hit === undefined) { covered = false; break; }
      if (hit > b) b = hit;
    }
    if (covered && (best === null || b - a < best[1] - best[0])) best = [a, b];
  }
  return best;
}

