function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let k, minLength, maxLength, span;
  if (size === 'large') {
    const shape = int(0, 2);
    k = [390, 1800, 390][shape];
    minLength = [50, 1, 50][shape];
    maxLength = [50, 10, 50][shape];
    span = [100000, 100000, 300][shape];
  } else {
    k = int(1, 4);
    minLength = 1;
    maxLength = 5;
    span = int(1, 12);
  }
  const nums = [];
  for (let i = 0; i < k; i++) {
    const length = int(minLength, maxLength);
    const list = Array.from({ length }, () => int(-span, span));
    list.sort((x, y) => x - y);
    nums.push(list);
  }
  return [nums];
}
